{
  "name": "claude-ai-engineering",
  "owner": {
    "name": "Jay Kim",
    "url": "https://github.com/JayKim88"
  },
  "description": "AI Engineering toolkit with Claude Code plugins for learning, project analysis, and multi-agent workflows",
  "plugins": [
    {
      "name": "learning-summary",
      "description": "Capture and document key learnings from conversations with structured markdown output",
      "source": "./plugins/learning-summary"
    },
    {
      "name": "project-insight",
      "description": "Comprehensive project analysis using multi-agent insights pipeline",
      "source": "./plugins/project-insight"
    },
    {
      "name": "ai-digest",
      "description": "Digest AI/tech articles and content into structured learning documents",
      "source": "./plugins/ai-digest"
    },
    {
      "name": "spec-interview",
      "description": "AI-driven requirements gathering through in-depth interviews to create comprehensive specifications",
      "source": "./plugins/spec-interview"
    },
    {
      "name": "ai-news-digest",
      "description": "Aggregates latest AI news from multiple RSS sources and generates curated Top 5 digest on-demand",
      "source": "./plugins/ai-news-digest"
    },
    {
      "name": "market-pulse",
      "description": "Financial market analysis dashboard with value investing tools (v2.0). US/Korean/Crypto markets + Graham/Lynch/Buffett analysis + safety margin calculation + GARP screening + investment firm-style reports",
      "source": "./plugins/market-pulse"
    },
    {
      "name": "future-architect",
      "description": "Organize thoughts and create actionable plans with Mermaid diagrams and prioritized TODOs",
      "source": "./plugins/future-architect"
    },
    {
      "name": "competitive-agents",
      "description": "Dual-agent competitive generation with cross-review, improvement rounds, and judge evaluation for plugin creation",
      "source": "./plugins/competitive-agents"
    },
    {
      "name": "portfolio-analyzer-fused",
      "description": "AI-powered portfolio management with multi-agent analysis. Stock scoring, risk analytics, opportunity finding, and conversational advisor (Competitive-Agents Fusion)",
      "source": "./plugins/portfolio-analyzer-fused"
    },
    {
      "name": "spec-validator",
      "description": "Validates implementation code against specification documents using YAML-based checklists and 4-dimension scoring (Competitive-Agents Winner - Agent Beta)",
      "source": "./plugins/spec-validator"
    },
    {
      "name": "business-avengers",
      "description": "AI partner organization for solo entrepreneurs. 23 AI agents + You as CEO that plan, research, design, develop, market, and monetize your online service from idea to launch with sprint cycles",
      "source": "./plugins/business-avengers"
    },
    {
      "name": "blog-generator",
      "description": "Transform technical notes and content into well-structured blog posts with narrative flow and SEO optimization",
      "source": "./plugins/blog-generator"
    },
    {
      "name": "career-compass",
      "description": "AI-powered career path analysis with 8-agent pipeline: resume analysis, market trends, skill gap assessment, and personalized roadmap",
      "source": "./plugins/career-compass"
    },
    {
      "name": "factor-lab",
      "description": "Quantitative stock screening and backtesting platform with multi-factor analysis and systematic trading strategies",
      "source": "./plugins/factor-lab"
    },
    {
      "name": "jd-analyzer",
      "description": "Job description analysis with multi-source collection from LinkedIn/Wellfound and skill matching for career transitions",
      "source": "./plugins/jd-analyzer"
    },
    {
      "name": "planning-interview",
      "description": "Adaptive product planning interviews that transform vague ideas into comprehensive PRDs (Lean Canvas, Product Brief, Full PRD)",
      "source": "./plugins/planning-interview"
    },
    {
      "name": "portfolio-copilot",
      "description": "AI-powered portfolio management and stock analysis with comprehensive scoring, P&L tracking, and interactive dashboards",
      "source": "./plugins/portfolio-copilot"
    },
    {
      "name": "rich-guide",
      "description": "Personalized wealth strategy system with 6 AI agents: financial diagnosis, market analysis, strategy generation, risk evaluation, and action roadmap (Korean)",
      "source": "./plugins/rich-guide"
    },
    {
      "name": "wrap-up",
      "description": "Document session work history and todos into a per-project wrap-up file that accumulates across sessions",
      "source": "./plugins/wrap-up"
    }
  ]
}
